import {strategyModules} from "./strategy-setups";
import type {Lesson} from '@/types';
// Append-only curriculum: existing lesson IDs and earned XP remain valid.
type Content=[string,string,string,string,string,string,string,string];
export const expandedModules=[
 {title:'Money Foundations',track:'Personal finance',reward:'Financial Foundations',content:[
 ['Starting with the amount that fits you','There is no single amount everyone needs to start learning about money or trading. Sprout lets you learn and practice without depositing real money. Actual investing requirements vary: some brokers offer fractional shares, while particular accounts or products have minimums. The best time to begin learning is now; committing real money should follow your budget, emergency needs, debt situation, and understanding of risk.','Someone with $5 available can begin learning today. Someone with $5,000 still needs a plan. Neither should borrow or use essential bill money just to trade.','Separate beginning your education from deciding when and how much real money to risk.','What can you begin without a fixed starting balance?','Learning and virtual practice','Every leveraged product','Guaranteed profitable trading'],
 ['Your net worth, without the jargon','Net worth is what you own minus what you owe. Assets include cash and property; liabilities include loans and credit balances. A positive number is not the same as available spending money: a house or retirement account may not be easy to access. Use consistent estimates and review changes over time rather than comparing yourself with others.','$2,000 in savings plus $3,000 in assets minus $1,500 in debt gives $3,500 net worth. The amount available to pay this month’s bills can be much smaller.','A whole financial picture is more useful than one account balance.','How do you calculate net worth?','Assets minus liabilities','Income minus groceries only','The value of your largest asset'],
 ['Give each financial goal a timeframe','A goal needs a purpose, an approximate cost, a timeframe, and an amount you can set aside. Near-term essential spending usually calls for accessible, relatively stable funds. Money exposed to markets may lose value just before you need it. Update goals as your circumstances change; a deadline does not make a return certain.','A deposit needed in three months and retirement thirty years away are different goals. Putting both into the same volatile trading position ignores when the money is needed.','Match the plan to the purpose, rather than chasing the largest quoted return.','What should guide a goal’s financial plan?','Purpose, timeframe, and capacity for loss','Only this week’s best stock','Someone else’s account size'],
 ['Time, opportunity cost, and financial choices','Opportunity cost is what you give up by choosing one use for money or time over another. Trading requires study and attention as well as capital. Compare a decision with alternatives such as reducing expensive debt, saving for essentials, or long-term investing. A choice can be reasonable even if another option later earns more.','Two hours researching a trade cannot also be spent on paid work. Paying down a high-interest balance may have a more predictable benefit than hoping for a trading gain.','Include time and alternatives when evaluating a financial opportunity.','What is opportunity cost?','The alternative you give up','A guaranteed transaction fee','A stock’s highest historical price'],
 ] as Content[]},
 {title:'Budgeting & Cash Flow',track:'Personal finance',reward:'Cash Flow Planner',content:[
 ['Gross income, take-home pay, and cash flow','Gross income is pay before deductions. Take-home pay is what arrives after items such as taxes and benefits. Cash flow compares money coming in with money going out during a period. Use actual timing: an annual salary figure does not mean the full amount is available today. Review statements to understand what you can consistently afford.','$3,000 take-home pay minus $2,700 monthly spending leaves $300 before unexpected costs. A $40,000 gross salary cannot be used as the monthly spending budget.','Start a plan with available cash rather than an optimistic headline number.','Which amount normally funds monthly spending?','Available take-home pay','Annual gross salary every month','A hoped-for trading gain'],
 ['Needs, wants, and fixed versus variable costs','Needs support essential living; wants add comfort or enjoyment. Fixed costs recur at relatively stable amounts; variable costs change. These are planning categories, not moral judgments. Some necessary costs are variable, such as groceries. Look for adjustments you can sustain, and allow room for irregular necessities rather than assuming every month will be identical.','Rent may be fixed and essential. Groceries are essential but variable. A subscription may be fixed yet optional. Categorize both purpose and behavior before cutting spending.','Understand which expenses you can change and which need reliable funding.','Can an essential expense be variable?','Yes, groceries are one example','No, every need is fixed','Only when it is paid in cash'],
 ['Build a budget you can actually follow','A budget is a plan for income, expenses, saving, and debt repayment. Methods include assigning every dollar a purpose or using broad percentage categories. Rules such as 50/30/20 are examples, not universal requirements. Compare the plan with actual spending and adjust it when reality differs. Include a buffer before assigning money to discretionary risk.','If housing consumes more than a suggested percentage, forcing a generic rule may not work. Start with your actual essential costs and choose achievable savings and debt amounts.','An adaptable budget is more useful than a perfect-looking spreadsheet you cannot follow.','How should a generic budget rule be used?','As a starting example to adapt','As a law everyone must meet','As a reason to skip bills'],
 ['Irregular expenses and sinking funds','A sinking fund sets aside money gradually for an expected future expense. It differs from an emergency fund, which covers unexpected needs. Include annual bills, maintenance, and seasonal income in cash-flow planning. When income varies, use a conservative baseline and review cash reserves before treating a strong month as permanent spending capacity.','A $600 annual insurance bill can be funded with $50 per month. That money is already assigned even if the bill will not arrive until later.','Prepare for predictable costs so they do not become avoidable financial surprises.','What is a sinking fund for?','An expected future expense','Only an unexpected job loss','Guaranteed trading profits'],
 ] as Content[]},
 {title:'Saving, Banking & Inflation',track:'Personal finance',reward:'Savings Steward',content:[
 ['Build an emergency buffer for your situation','An emergency fund is accessible money for essential unexpected expenses or income disruption. Suggested months of expenses are planning ranges, not a number everyone must reach immediately. The right buffer depends on income stability, dependents, insurance, and obligations. Start with an achievable amount and build gradually. Volatile trading positions can lose value when you need cash most.','Someone with irregular income may need a larger buffer than someone with stable income and fewer obligations. Starting with a small reserve is still progress.','Protect essential spending before assigning money to speculative activity.','Where should an emergency buffer usually be accessible?','In relatively stable, accessible funds','Only in a volatile single stock','Only in an open day trade'],
 ['Checking, savings, and deposit protection','Checking accounts support payments; savings accounts may pay interest with different access terms. In the US, eligible deposits at FDIC-insured banks and federally insured credit unions have protection subject to limits and ownership categories. Common coverage is $250,000 per depositor, per institution, per ownership category. Verify the institution and coverage; investments and crypto are not ordinary insured deposits.','Two accounts with the same bank under the same ownership category do not automatically double the insurance limit. A brokerage cash sweep may involve specific partner banks and separate terms.','Understand what protects cash and what does not protect market losses.','Does deposit insurance ordinarily cover stock price losses?','No, market investments are different','Yes, every finance app balance','Yes, if the stock is popular'],
 ['Interest, APR, and APY','Interest is money paid for lending or using money. APR describes an annualized rate, often for borrowing; APY reflects the effect of compounding over a year for a stated deposit rate. Compare fees, access, introductory terms, and how frequently the rate can change. A higher advertised rate may come with conditions and is not always fixed.','A savings account quoting APY includes its stated compounding assumptions. A loan’s full cost also depends on fees and repayment terms, not just its monthly payment.','Compare products on consistent terms and read conditions before choosing.','What does APY generally include?','The effect of compounding','A guarantee the rate never changes','Every possible account fee'],
 ['Inflation and purchasing power','Inflation means prices generally rise over time, reducing how much a dollar buys. Nominal return is the stated change in money; real return adjusts for inflation. An approximate real return subtracts inflation, while a more precise calculation uses (1 + nominal return) / (1 + inflation) − 1. Inflation measures vary and do not exactly match every household’s spending.','A 4% nominal gain with 3% inflation gives about 0.97% real growth, not a 4% increase in purchasing power. A cash balance can stay constant while buying less.','Evaluate money in terms of what it can buy as well as its dollar amount.','What does real return adjust for?','Inflation','Only the company’s share count','Your personal confidence'],
 ] as Content[]},
 {title:'Debt & Credit',track:'Personal finance',reward:'Credit Clarity',content:[
 ['Understand the full cost of debt','Debt creates a repayment obligation whether your investments rise or fall. Compare interest rates, fees, repayment terms, and whether collateral is at risk. Minimum payments may reduce a balance slowly and leave substantial interest costs. Borrowing to trade can combine a certain debt obligation with an uncertain market outcome. Read statements and agreements instead of judging a loan only by an affordable-looking payment.','A credit balance charging 24% APR can cost much more than an investment might earn. Trading profits cannot be assumed to cover the interest or required payments.','Account for obligations before deciding how much discretionary risk you can take.','Does a trading loss remove your loan obligation?','No, repayment terms still apply','Yes, losses cancel the balance','Only if the trade was short-term'],
 ['Compound interest can help or hurt','Compounding means interest or returns affect the next period’s base. On savings it may support growth; on unpaid borrowing it can increase costs. Investment returns fluctuate, so a smooth compound-growth illustration is not a forecast. Contributions, withdrawals, fees, and timing also change outcomes. Use calculations to compare assumptions, not to promise a future balance.','$1,000 growing at a hypothetical steady 5% annually becomes $1,102.50 after two years. Real markets do not provide the same fixed return every year.','Understand which side of compounding you are on.','Why is a constant-return illustration not a market guarantee?','Real returns vary and can be negative','Compounding never occurs','Only banks can use percentages'],
 ['Avalanche and snowball repayment methods','The avalanche method prioritizes extra payments toward the highest interest rate after required minimums. The snowball method prioritizes the smallest balance for visible progress. Avalanche can reduce interest costs under consistent assumptions; snowball may support motivation. Keep required payments on every debt, check penalties, and choose a sustainable plan rather than abandoning it after one difficult month.','For $500 at 10% and $2,000 at 25%, avalanche targets the 25% balance first. Snowball targets the $500 balance first while minimums on both continue.','A clear repayment method turns a broad goal into repeatable actions.','Which balance does avalanche prioritize?','The highest interest rate','Always the smallest balance','Always the newest lender'],
 ['Credit reports, utilization, and payment history','A credit report records credit activity; a score summarizes parts of that information using a particular model. Payment history and amounts owed often matter significantly. Utilization compares revolving balances with limits. Models and lenders differ, so no single action guarantees a particular score increase. Review reports for errors and use official channels to dispute inaccuracies.','A $500 reported balance on a $2,000 card limit is 25% utilization. Paying on time and correcting errors are different tasks; opening many new accounts solely for a score can backfire.','Understand borrowing access without treating a score as your personal worth.','What is utilization on a $500 balance and $2,000 limit?','25%','4%','250%'],
 ] as Content[]},
 {title:'Investment Building Blocks',track:'Personal finance',reward:'Asset Explorer',content:[
 ['Stocks versus bonds','A stock represents ownership; a bond generally represents lending to an issuer under stated terms. Stockholders and bondholders have different claims and risks. Bond prices can move, issuers can default, and inflation can erode payments. A mix of asset types may change portfolio behavior but cannot eliminate loss. Read the instrument’s terms rather than assuming every bond is safe.','A bond promising interest is not the same as owning part of a company. Selling that bond before maturity may produce a gain or loss as market rates and credit expectations change.','Know what you own and which risks drive its value.','What does a bond usually represent?','A lending obligation','Voting ownership in every issuer','A guaranteed rising market price'],
 ['ETFs, mutual funds, and index funds','Funds hold collections of assets under a stated strategy. ETFs typically trade on an exchange; mutual funds commonly transact at a calculated end-of-day value, subject to fund terms. An index fund follows a specified index, and can be an ETF or mutual fund. Check holdings, concentration, fees, liquidity, and whether leverage or derivatives change the exposure.','An ETF concentrated in one industry can still be risky despite holding multiple stocks. A broad index fund and a leveraged daily ETF are not interchangeable.','A fund label does not tell you everything about its diversification or risk.','Can an index fund be an ETF?','Yes, index describes the strategy','No, ETFs cannot follow indexes','Only if it holds one stock'],
 ['Dividends, distributions, and total return','A dividend is a company payment to shareholders; fund distributions may include income or other gains. Payments can change or stop. The market price often adjusts around an ex-dividend date, so a payment is not free money added without other effects. Total return considers price change plus relevant distributions, with fees and taxes affecting what you keep.','A $100 share paying $2 does not automatically leave you with a $100 share plus a risk-free $2. The price can adjust and continue moving for other reasons.','Compare overall outcomes rather than focusing on yield alone.','What should total return consider?','Price changes and distributions','Only the advertised yield','Only how often a payment arrives'],
 ['Cash, real assets, and alternative investments','Different assets expose you to different sources of risk. Cash emphasizes access and stability but can lose purchasing power. Property may involve maintenance and low liquidity. Commodities can respond to supply and demand. Private or complex products may limit withdrawals and charge substantial fees. Understand valuation, custody, access, and potential loss before treating an unfamiliar asset as diversification.','A property cannot usually be sold as quickly as an exchange-traded fund. A private investment’s displayed valuation may not be the price available if you need to exit.','Diversification also requires understanding how and when you can access money.','What does liquidity describe?','How readily an asset can be converted or traded','Whether it must earn a profit','Its number of online followers'],
 ] as Content[]},
 {title:'Long-Term Portfolio Planning',track:'Personal finance',reward:'Portfolio Planner',content:[
 ['Diversification and correlation','Diversification spreads exposure across assets or sources of risk. Correlation describes how returns move together, and can change during stress. Owning many highly similar holdings may leave you concentrated in one risk. Diversification can reduce some company-specific risk but cannot remove broad market losses. Look through fund holdings to identify overlaps.','Three technology funds may all hold the same large companies. Ten ticker symbols do not necessarily provide ten independent sources of risk.','Measure exposures rather than counting logos in a portfolio.','Does holding many similar funds guarantee diversification?','No, their underlying exposures can overlap','Yes, each ticker eliminates risk','Only if they have different colors'],
 ['Asset allocation and your capacity for loss','Asset allocation is how money is divided among asset categories. Risk tolerance is your comfort with uncertainty; risk capacity is your financial ability to absorb loss. Goals, time horizon, income, obligations, and liquidity needs all matter. A questionnaire or age-based shortcut is a starting tool, not a complete personal plan. Review allocation when circumstances change.','Someone comfortable with price swings may still need stable money for next month’s rent. Psychological comfort does not replace financial capacity.','Use both practical needs and comfort level when choosing exposure.','What is risk capacity?','Financial ability to absorb loss','Only how exciting trading feels','The maximum broker leverage'],
 ['Rebalancing without chasing winners','Rebalancing brings a portfolio toward a chosen allocation when market moves or contributions change the mix. Methods include scheduled reviews or deviation thresholds. Selling and buying may create costs and taxes; directing new contributions can sometimes adjust weights without selling. Rebalancing maintains a plan rather than guaranteeing better returns.','A target 60% stock allocation growing to 75% changes the portfolio’s risk. A review may use new savings or trades to move closer to the chosen target.','Avoid letting a recent winner silently redefine the risk you intended to take.','What is the primary purpose of rebalancing?','Restore a chosen allocation','Guarantee this year’s highest return','Buy whatever rose most today'],
 ['Regular contributions and uncertain markets','Regular investing spreads purchases across dates. It can make contributions consistent and reduce dependence on choosing one entry time, but it does not prevent losses. Investing a lump sum versus gradually involves tradeoffs in exposure and timing; neither method always wins. Keep essential cash needs separate and consider fees, available funds, and your horizon.','Buying $50 of an eligible investment monthly creates a habit. If its price falls for a prolonged period, the account can still lose value despite repeated contributions.','A sustainable contribution process is different from a guaranteed outcome.','Do regular purchases remove market risk?','No, the investment can still fall','Yes, after three purchases','Only when the contribution is small'],
 ] as Content[]},
 {title:'Taxes & Financial Records',track:'Personal finance',reward:'Record Keeper',content:[
 ['Realized gains and investment income','US tax treatment depends on the asset, account, holding period, and individual circumstances. Selling can realize a gain or loss; dividends and interest can also create taxable income in a taxable account. A portfolio screen is not a tax return. Sprout uses virtual money and does not produce real investment gains or tax forms. Verify current official guidance for actual transactions.','Selling a real investment above its adjusted cost may create a taxable gain even if the cash remains in the brokerage account. A virtual Sprout sale is only practice.','Keep tax obligations separate from an app’s displayed performance.','Can a taxable sale matter even without a bank withdrawal?','Yes, realization and withdrawal are different','No, only withdrawals can be taxable','Only if the broker closes'],
 ['Holding periods and capital gains','In the US, gains on many capital assets held more than one year may receive long-term treatment; shorter holdings generally have different treatment. Rates and exceptions depend on income, asset type, and current law. State taxes may also apply. Do not assume a profitable trade’s gross gain is the amount you keep. Compare after-cost and after-tax outcomes where applicable.','A position sold after six months is not automatically long-term merely because you intended to invest. Actual acquisition and sale dates matter.','Trading frequency and holding periods can change the practical outcome.','What commonly determines short- versus long-term classification?','The actual holding period under applicable rules','Your intention when buying','The color of the chart'],
 ['Wash sales and careful loss records','For certain US securities, buying a substantially identical security within 30 days before or after a loss sale can defer a loss under wash-sale rules. Purchases in other accounts and by related parties can complicate treatment. This is not simply a rule about selling twice on one day. Asset coverage and special situations require current guidance; keep detailed records and seek qualified tax help when needed.','Selling a stock at a loss and repurchasing it a week later may create a wash sale. The loss is generally adjusted or deferred rather than simply deducted as originally expected.','Frequent trading can make tax recordkeeping more complex than the trade history suggests.','Can a purchase before a loss sale matter for wash-sale rules?','Yes, the window includes days before and after','No, only purchases after matter','Only purchases in Sprout count'],
 ['Cost basis, statements, and reconciliation','Cost basis is the amount used to determine a gain or loss, with adjustments depending on the investment and rules. Record acquisition dates, quantities, prices, fees, distributions, and corporate actions. Reconcile records with broker statements and tax forms; transferred positions or multiple accounts can introduce errors. Save documentation securely for applicable retention periods.','A stock split changes share quantities and per-share basis without creating a simple price-based profit. Missing that adjustment can distort both records and tax calculations.','Accurate records support better decisions and fewer reporting mistakes.','What should you do with broker statements and personal records?','Reconcile them and investigate differences','Assume all differences are trading gains','Discard them after each sale'],
 ] as Content[]},
 {title:'Retirement & Tax-Advantaged Accounts',track:'Personal finance',reward:'Future Planner',content:[
 ['Employer plans: 401(k) and matching','US employer plans such as 401(k) and 403(b) plans may offer a contribution match subject to plan rules and vesting. A match can be valuable, but contributions, investments, withdrawal limits, and fees still need review. US contribution limits and eligibility can change annually. Read the plan documents and current official limits rather than treating an example as a universal entitlement.','A plan might match part of your contribution up to a salary percentage. If vesting applies, leaving early can affect ownership of employer contributions.','Understand available workplace benefits before assigning all spare money to trading.','What can affect ownership of employer matching contributions?','The plan’s vesting rules','Your last stock trade','The broker’s chart timeframe'],
 ['Traditional versus Roth: timing of taxes','Traditional and Roth describe different tax treatment, subject to account-specific eligibility and rules. Traditional contributions may provide a deduction or pre-tax treatment; withdrawals can be taxable. Roth contributions generally use after-tax money, with qualified withdrawals potentially tax-free. The comparison depends on current and future circumstances and applicable rules, not a label that is always best for everyone.','Two people with different income, eligibility, and expected retirement circumstances may reasonably choose different account treatment. Qualified withdrawal conditions still matter.','Choose account treatment deliberately rather than assuming one type always wins.','What is a key Traditional-versus-Roth distinction?','When taxes may apply','Whether investments can lose value','Whether stock charts are available'],
 ['IRAs, eligibility, and withdrawal conditions','Individual retirement accounts have contribution, eligibility, and withdrawal rules that vary by type and current law. A retirement account is a tax wrapper, not an investment by itself: you still choose assets inside it. Early withdrawals may have taxes or penalties, with exceptions that require careful review. Consult official current rules before contributing or withdrawing.','Opening an IRA does not necessarily invest deposited cash automatically. Check both the account rules and what the money actually holds.','An appropriate account and an appropriate investment are separate decisions.','Does opening an IRA automatically select an investment?','Not necessarily; check what the cash holds','Yes, it always buys one stock','Yes, it guarantees growth'],
 ['HSAs and planning for healthcare','In the US, Health Savings Accounts require eligibility linked to qualifying coverage and other conditions. Contributions, earnings, and qualified withdrawals may receive tax benefits, but limits and rules apply. HSAs differ from Flexible Spending Accounts. Keep expense documentation and verify eligibility and withdrawal treatment with current official guidance. Investment options may add market risk to money needed for healthcare.','A qualified medical expense may have different HSA treatment from a nonqualified withdrawal. The name “health account” does not make every purchase eligible.','Understand healthcare account rules before treating them as unrestricted cash.','What should determine whether an HSA expense qualifies?','Applicable rules and proper documentation','Whether the purchase feels healthy','Whether the account has investments'],
 ] as Content[]},
 {title:'Protecting Your Finances',track:'Personal finance',reward:'Financial Safeguard',content:[
 ['Insurance, deductibles, and financial protection','Insurance transfers specified risks under a contract; it does not cover everything. Premiums are payments for coverage, deductibles are amounts you may pay before certain benefits apply, and limits cap coverage. Consider health, property, liability, disability, and life needs according to your situation. Read exclusions and compare the full coverage rather than only the cheapest premium.','A low premium with a large deductible may require more cash if a covered event occurs. A policy may exclude a particular event even when the loss is substantial.','Protect financial stability from risks that a trading gain cannot reliably solve.','What should you compare besides an insurance premium?','Coverage, exclusions, limits, and deductible','Only the logo','Only the stock price of the insurer'],
 ['Recognize scams and unrealistic promises','Guaranteed high returns, pressure to act immediately, secret strategies, and requests to send money to unusual destinations are warning signs. Verify firms and professionals through official regulators, using independently located contact information. Popularity, testimonials, screenshots, and celebrity images are not proof of legitimacy. Pause before transferring money or sharing access credentials.','A message promising to double money this week and asking for an upfront crypto payment is a reason to stop and investigate, not a reason to hurry.','Time to verify can protect you from an avoidable loss.','Which claim is a warning sign?','Guaranteed high returns with urgent payment demands','Clear discussion of uncertainty','Transparent fees and verified registration'],
 ['Account security and phishing','Use unique strong passwords, a password manager when appropriate, and multifactor authentication. Phishing imitates trusted organizations to capture credentials or payments. Check domains and use saved official links rather than unsolicited messages. Keep recovery methods secure, update devices, and review account activity. Support staff should not need your password or one-time authentication code.','An email showing a familiar logo can still link to a lookalike domain. Open the official site independently before entering credentials or acting on an urgent request.','Protecting account access is part of managing financial risk.','Should you send a one-time login code to someone claiming to be support?','No, keep authentication codes private','Yes, if their avatar looks official','Only if they promise faster service'],
 ['Beneficiaries, documents, and trusted contacts','Beneficiary designations, wills, powers of attorney, and trusted contacts serve different purposes. Account-specific designations may control transfers independently of a will, subject to law and circumstances. Keep information current after major life events. A trusted contact is not automatically authorized to trade or withdraw. Estate and legal planning varies by jurisdiction and may need professional help.','Updating a will may not update the beneficiary listed on a retirement account. Review both documents and account records rather than assuming one change covers everything.','Planning includes how finances are handled when you cannot manage them yourself.','Does a trusted contact automatically have trading authority?','No, those roles are different','Yes, on every account','Only when a stock falls'],
 ] as Content[]},
 {title:'Money Decisions Across Life',track:'Personal finance',reward:'Life Goals Planner',content:[
 ['Renting, buying, and the full cost of housing','Compare housing choices using total costs, expected time in the home, available cash, and uncertainty. Owning may include interest, taxes, insurance, maintenance, and transaction costs. Renting may offer flexibility with different risks and terms. A mortgage payment is not the full cost of ownership, and property prices can fall. Local markets and personal circumstances matter.','A mortgage costing the same as rent can still involve repairs and closing costs. A likely move next year changes the comparison because transaction costs may be significant.','Evaluate housing as a financial and practical decision, not a universal rule.','Is the mortgage payment the entire cost of owning?','No, other ongoing and transaction costs matter','Yes, repairs are always free','Only if the house is new'],
 ['Education costs and borrowing decisions','Education can create opportunities, but its financial return varies. Compare tuition, living costs, completion likelihood, grants, loan terms, and realistic career paths. Understand repayment requirements and any program-specific conditions. A promised salary is not guaranteed. Plan how payments fit the budget rather than evaluating a loan only by whether approval is available.','Two programs with similar titles can have different costs and outcomes. Grants, completion rates, and likely earnings can change the borrowing decision substantially.','Treat educational borrowing as an informed commitment rather than an automatic investment return.','What should an education borrowing decision include?','Costs, loan terms, and realistic outcomes','Only the maximum loan offered','Only a promotional salary claim'],
 ['Financial habits and automation','Automation can support regular saving, bill payments, and planned contributions, but it still needs review. Keep enough cash for scheduled payments, check fees and balance alerts, and update transfers when income or obligations change. A habit should serve your plan rather than quietly moving money into risk you no longer intend to take.','A monthly savings transfer is helpful until a change in income makes it overdraft the checking account. Reviewing the schedule keeps automation aligned with current cash flow.','Consistency is useful when the process remains affordable and deliberate.','Does automation remove the need to review finances?','No, circumstances and balances can change','Yes, permanently','Only if transfers are weekly'],
 ['Plan a financial review you will repeat','A useful review checks income, spending, debt, savings, goals, insurance, and investment exposure. Set a cadence that fits your situation and review after major changes. Separate actionable issues from market noise. Keep a short list of next steps and know when qualified financial, tax, or legal advice is appropriate. Progress does not require fixing every topic in one day.','A monthly check might identify one subscription to cancel, a savings transfer to adjust, and a credit-report error to investigate. Daily stock price watching would not solve those issues.','A repeatable review turns knowledge into practical decisions.','What makes a financial review useful?','Checking the whole situation and selecting actionable steps','Only watching the hottest ticker','Making the maximum number of trades'],
 ] as Content[]},
 {title:'Market Structure & Execution',track:'Advanced trading',reward:'Execution Analyst',content:[
 ['Order books, liquidity, and market impact','An order book shows displayed buying and selling interest at price levels. Displayed liquidity can change or disappear and may not represent all available interest. A larger market order can consume multiple levels and move the execution price. Sprout generates prices and does not model a real order book, routing, or market impact. Learn the concepts before assuming a quote guarantees a fill.','Buying 500 shares when only 100 are offered at the best ask may require higher prices for the rest. A screen’s last price alone cannot show that full cost.','Execution quality depends on available liquidity, not only your direction forecast.','Can a large market order fill at multiple prices?','Yes, available liquidity may span several levels','No, the last price fixes every share','Only when its ticker is long'],
 ['Spreads, slippage, and trading costs','The bid-ask spread is the difference between quoted buying and selling prices. Slippage is a difference between an expected execution price and the price obtained. Commissions, exchange fees, spreads, borrowing costs, and taxes can affect results. Zero advertised commissions do not mean zero total cost. Costs matter especially when a strategy trades frequently or targets small moves.','A strategy expecting five cents per share can be overwhelmed by spreads and unfavorable fills. A commission-free account can still incur those economic costs.','Judge a strategy after realistic costs rather than using an ideal entry price.','Does zero commission mean every trade has zero cost?','No, spreads and other costs can remain','Yes, by definition','Only for trades made quickly'],
 ['Partial fills, order priority, and uncertain execution','Orders can fill partially, remain open, or fail to execute depending on order type and conditions. Price and time priority are common concepts, but venue rules differ. A limit order controls the acceptable price condition; it does not guarantee a fill. Cancel requests and order acknowledgments also take time. Sprout’s simplified fills do not reproduce every exchange or broker behavior.','You request 100 shares at a limit but only 20 trade at that price. The remaining 80 may stay open. Price touching your limit on a chart does not prove all 100 were available to you.','Understand execution uncertainty before relying on a backtest’s assumed fills.','What can happen to a limit order?','It can remain unfilled or fill only partly','It must fill immediately','It guarantees a profit after filling'],
 ['Halts, gaps, and changing market conditions','Trading halts and pauses can interrupt execution. When trading resumes, prices may move sharply, and orders may behave according to venue and broker rules. Gaps can move past planned exits; a stop price is not necessarily a guaranteed execution price. Session availability, order handling, and instruments differ. Sprout runs continuously and does not reproduce real halts or exchange schedules.','A stock closing at $100 and reopening at $85 may move past a planned $95 stop. A model that always fills at $95 understates the possible loss.','Plan for conditions that make ordinary assumptions fail.','Can a gap make a loss larger than a planned stop distance?','Yes, execution may occur beyond that price','No, stops guarantee every price','Only if the chart is red'],
 ] as Content[]},
 {title:'Fundamental Analysis & Valuation',track:'Advanced trading',reward:'Business Analyst',content:[
 ['Revenue, profit, and financial statements','Revenue measures sales; profit reflects costs and other accounting items. The income statement, balance sheet, and cash-flow statement describe different parts of a business. Accounting profit and cash generation can differ. Read periods consistently and understand whether numbers are reported under comparable rules. One attractive metric does not establish that a stock is undervalued.','A company can grow revenue while margins shrink and cash flow weakens. Rising sales alone do not show how much value remains for owners.','Evaluate the business behind the ticker rather than one promotional number.','Does revenue growth automatically mean profit growth?','No, costs and margins can change','Yes, by the same percentage','Only for large companies'],
 ['Cash flow, debt, and business resilience','Cash flow shows cash generated or used across operations, investing, and financing. Debt terms, maturity schedules, interest costs, and available liquidity affect resilience. Free cash flow definitions can differ, so check what a company or analyst subtracts. Compare figures with the business model and avoid treating a temporary cash inflow as sustainable operating strength.','Borrowing can increase cash without improving operating performance. A company with large near-term debt maturities may face refinancing risk even while reporting accounting profit.','Understand how a company funds operations and survives difficult periods.','Does new borrowing necessarily mean stronger operating cash generation?','No, financing and operations are different','Yes, every cash increase is operating profit','Only when shares rise'],
 ['Valuation ratios need context','Ratios such as price-to-earnings, price-to-sales, and enterprise-value measures compare price with chosen financial metrics. Denominators can be negative, cyclical, or adjusted. Compare businesses with similar economics and account for growth, margins, debt, and uncertainty. A low ratio may indicate risk rather than a bargain; a high ratio may reflect expectations that can disappoint.','Two companies with the same P/E can have different debt, growth, and earnings quality. A temporarily high profit can make a cyclical business look artificially cheap.','Use valuation as an argument to examine, not a standalone buy instruction.','Does a low P/E prove a stock is a bargain?','No, business conditions and expectations matter','Yes, it guarantees a rebound','Only when the price is below $10'],
 ['Earnings expectations and corporate actions','Prices respond to results relative to expectations as well as absolute performance. Guidance, buybacks, dilution, splits, mergers, and distributions can change interpretation. A stock split changes units and per-share prices without automatically creating economic value. Read official filings and distinguish confirmed information from speculation. News interpretation can remain uncertain even after a release.','A company can report higher profit yet fall if investors expected stronger growth. A two-for-one split doubles shares and roughly halves the corresponding per-share price, before other market moves.','Understand what changed economically rather than judging only a headline or share count.','Does a stock split alone double the value of your holding?','No, units and per-share prices adjust','Yes, automatically','Only when announced after hours'],
 ] as Content[]},
 {title:'Macroeconomics & Market Context',track:'Advanced trading',reward:'Market Context Reader',content:[
 ['Interest rates and asset prices','Interest rates influence borrowing costs, discount rates, and the attractiveness of alternatives. Policy announcements can affect prices, but markets also respond to what was expected and to future guidance. A rate change does not mechanically move every asset in the same direction. Duration, debt exposure, business conditions, and market positioning can change the response.','A widely expected rate cut may already be reflected in prices. New guidance suggesting fewer future cuts can matter more than the immediate change.','Consider expectations and transmission mechanisms instead of relying on one simple rule.','Does a rate cut guarantee every stock rises?','No, expectations and other factors matter','Yes, without exceptions','Only during regular hours'],
 ['Economic releases and surprise','Employment, inflation, output, and other releases offer partial views of economic conditions. Initial numbers may be revised, and different measures answer different questions. Markets often react to the difference between reported results and expectations. Know the release schedule and source, but do not assume you can reliably predict the reaction or obtain an ideal fill during volatility.','Inflation can fall yet exceed forecasts. A favorable-sounding direction may still disappoint expectations and trigger a different market response.','Read what a release measures and how it compares with expectations.','What can influence a reaction besides the headline direction?','The difference from expectations and later revisions','Only the font of the announcement','The number of trading apps open'],
 ['Sectors, cycles, and interconnected risks','Businesses can respond differently to growth, financing costs, commodity prices, and consumer behavior. Sector categories are useful summaries but hide differences between companies. Economic cycles do not follow a fixed timetable. A sector view should include scenarios and what would contradict the idea, rather than assuming a historical sequence will repeat exactly.','Higher fuel costs can affect an airline differently from an energy producer. Both still face company-specific risks and broader market conditions.','Use context to identify exposures without treating a cycle as a clock.','Do economic cycles follow an exact trading schedule?','No, timing and effects remain uncertain','Yes, every sector turns monthly','Only when inflation is positive'],
 ['Event calendars and scenario planning','Scheduled events such as earnings and policy releases can alter volatility and liquidity. Unscheduled events can also matter. Build scenarios for different outcomes, note exposure across correlated holdings, and decide whether to reduce activity or observe. News access and speed vary, so a retail trader should not assume equal information or execution conditions with every participant.','Before earnings, write what you will do if price gaps in either direction. Choosing not to hold through the event is a valid scenario response.','A calendar supports preparation, not certainty about an announcement’s outcome.','What is a useful event plan?','Prepare for multiple outcomes and execution limits','Assume the expected outcome must occur','Increase size because the date is known'],
 ] as Content[]},
 {title:'Strategy Setups & Invalidation',track:'Advanced trading',reward:'Setup Planner',content:[
 ['Breakouts and failed breakouts','A breakout moves beyond an observed price area. Volume, timeframe, surrounding trend, and later behavior may provide context, but none guarantees continuation. False breakouts return inside the area. Define the condition, invalidation, position size, and exit logic before acting. Sprout examples illustrate possible paths; they do not establish that the setup has a profitable edge.','Price briefly moves above $100 and returns to $99. A rule based only on touching $100 would miss the possibility of a failed breakout.','Describe a setup and its failure condition before calling it an opportunity.','Can a breakout fail after crossing a prior level?','Yes, price can return inside the area','No, the crossing guarantees continuation','Only on a line chart'],
 ['Pullbacks in trends','A pullback is a move against an observed trend. Distinguish the trend timeframe from your entry timeframe, and identify what would indicate the trend may be changing. Buying a dip without a loss plan can turn a small idea into an uncontrolled position. Later confirmation may reduce some ambiguity while still leaving uncertainty and different execution prices.','Higher swings followed by a decline may be a pullback or the beginning of a reversal. Naming the past pattern does not decide which outcome comes next.','A trend describes observed behavior, not a promise that every dip recovers.','Does a dip in an uptrend guarantee a rebound?','No, the trend can change','Yes, if the trend lasted a week','Only if the stock pays dividends'],
 ['Ranges and mean reversion','Mean reversion describes movement back toward a reference level after deviation. In a range, traders may study repeated reactions near boundaries. The reference and timeframe must be defined, and a changing regime can invalidate the idea. A price far from an average can continue moving away. Consider costs, gaps, and the risk of repeatedly adding to a losing position.','A stock repeatedly trading between $20 and $22 can break below $20. Calling $20 “cheap” relative to the range does not ensure the old range remains relevant.','Distinguish a measured tendency from a belief that price must return.','Can a range boundary break?','Yes, conditions can change','No, repeated touches make it permanent','Only if the company changes its ticker'],
 ['News, gaps, and choosing to pass','Event-driven setups often involve rapid changes, uncertain information, and execution risk. A gap is a discontinuity between observed prices or sessions. The first move can reverse or continue, and spreads can widen. Write the setup and possible loss in advance where possible; when the conditions are unclear, observing without entering can be the strongest choice.','A stock opens 8% higher after news. Entering only because it is moving quickly provides no defined reason for the trade or condition for exiting.','You do not need to trade every visible opportunity to learn.','Is passing on an unclear setup a valid decision?','Yes, a trade is optional','No, every gap must be traded','Only after losing money'],
 ] as Content[]},
 {title:'Testing & Trading Systems',track:'Advanced trading',reward:'Evidence Builder',content:[
 ['Write a rule you can evaluate','A testable trading rule specifies the instrument universe, timeframe, entry condition, exit condition, sizing, and costs. Vague statements such as “buy strength” can be changed after the fact. Keep discretionary observations separate from precise rules, and record when and why a rule changes. A clear rule may still be unprofitable; clarity simply makes evaluation possible.','“Buy when it looks strong” is hard to test consistently. A defined condition with a stated exit and size can be checked against the same evidence repeatedly.','You cannot fairly judge a process that changes whenever the result disappoints.','What makes a rule testable?','Specific conditions, sizing, exits, and assumptions','A confident-sounding name','Changing the rule after every outcome'],
 ['Backtests and realistic assumptions','A backtest applies rules to historical data. Its results depend on data quality, trading costs, fills, corporate-action adjustments, and the information actually available at each decision. It does not recreate every real-world constraint. A profitable historical result is evidence to examine, not a guarantee of a future edge. Sprout generated price paths are practice scenarios rather than real market backtesting data.','Assuming a large order always fills at a candle’s best price can inflate performance. Ignoring delisted securities can also make an investment universe look better than it was.','Ask how a result was produced before trusting its headline return.','Does a profitable backtest guarantee future profits?','No, assumptions and conditions can differ','Yes, if it uses many charts','Only when the line is smooth'],
 ['Look-ahead bias, leakage, and survivorship','Look-ahead bias uses information that was not yet available at the decision time. Data leakage transfers future or test information into model selection. Survivorship bias excludes instruments or strategies that failed or disappeared. These errors can make a weak rule appear strong. Keep timestamps, historical membership, and data splits consistent with how a real decision would have been made.','Using the final day’s high to choose an entry earlier that same day uses future information. Testing only companies that remain listed today can omit historical failures.','A fair test must respect what was knowable at the time.','What is look-ahead bias?','Using future information in an earlier decision','Reviewing your journal later','Keeping dated transaction records'],
 ['Overfitting and forward practice','Overfitting adjusts rules too closely to a sample’s noise. Trying many combinations and presenting only the best can exaggerate apparent skill. Use appropriately separated evaluation data, account for repeated testing, and observe a rule forward without rewriting every result. Even a robust process can lose and degrade as conditions change. Judge evidence across uncertainty, costs, and practical execution.','A rule optimized to one unusually favorable month may fail immediately afterward. An unchanged forward-practice period tests whether the process can be followed under new conditions.','Protect yourself from confusing a finely tuned historical story with a durable process.','What helps evaluate overfitting risk?','Separate evaluation and unchanged forward observation','Selecting only the best historical month','Adding unlimited indicators until results look good'],
 ] as Content[]},
 {title:'Advanced Risk & Leverage',track:'Advanced trading',reward:'Risk Systems Thinker',content:[
 ['Leverage and margin amplify both directions','Leverage creates exposure larger than the capital supporting it. Borrowing and margin requirements can cause interest costs, forced sales, or losses beyond the amount initially committed in some products. Requirements can change during stress. Understand account and instrument terms before using leverage. Sprout does not provide margin borrowing or leveraged short execution.','A $1,000 equity amount supporting $2,000 exposure experiences about twice the percentage effect of a price move, before costs and changing margin requirements.','More exposure is also more sensitivity to an unfavorable outcome.','What does leverage amplify?','Both potential gains and losses','Only profitable moves','Only dividends'],
 ['Short selling and borrowing risk','Short selling generally involves selling borrowed shares and later buying them back. Borrow availability, fees, recalls, and margin requirements can affect the position. A rising price can create losses with no simple fixed upper bound for an uncovered short. A short squeeze can intensify pressure to buy back. Sprout teaches the concept but its stock simulator only sells shares you own.','Shorting at $50 and covering at $70 loses $20 per share before costs. A stock can rise far beyond $70; your initial sale price is not a maximum loss.','An unfamiliar execution direction can carry risks very different from buying shares.','Is an uncovered short’s loss capped at the sale price?','No, the price can rise far above it','Yes, exactly like a fully paid long','Only if the company is small'],
 ['Portfolio heat and correlated positions','Portfolio heat is a planning measure of combined intended risk across positions, based on defined assumptions. Several positions can respond to the same event, and stops may slip together. A sum of planned stop losses is not a worst-case loss guarantee. Evaluate concentration, correlation, liquidity, and cash needs rather than approving each trade independently.','Five positions each planning 1% loss may all respond to the same industry news. Their combined gap loss can exceed a simple 5% stop-based estimate.','Risk belongs to the whole account, not only one trade ticket.','Does adding planned stop risks guarantee a maximum account loss?','No, gaps and shared exposures can change losses','Yes, all exits are guaranteed','Only for more than ten positions'],
 ['Drawdown, recovery, and avoiding ruin','Drawdown measures a decline from an equity peak under specified data and cash-flow assumptions. Recovery percentages are asymmetric: a 50% loss needs a 100% gain to regain the original value. Repeated excessive risks can make recovery impractical or exhaust capital. Limit exposure based on what you can afford to lose, and examine losing streaks rather than assuming an average result will arrive immediately.','A $1,000 account falling to $500 needs $500 of gains: 100% of the remaining balance. Doubling size to recover can worsen the problem.','Preserving the ability to continue is a central part of risk planning.','What gain restores a balance after a 50% loss?','100% of the remaining balance','50% of the remaining balance','Any one winning trade'],
 ] as Content[]},
 {title:'Options Fundamentals',track:'Advanced trading',reward:'Options Concept Reader',content:[
 ['Calls, puts, and contract terms','An option gives its buyer specified rights involving an underlying asset, strike price, and expiration. A call generally gives a right to buy; a put gives a right to sell, subject to contract rules. The buyer pays a premium; the seller takes an obligation. Contract multipliers and settlement differ. Sprout does not execute options, and learning the vocabulary does not establish readiness to trade them.','One standard US equity option commonly relates to 100 shares, but adjustments and other products can differ. A quoted premium needs its multiplier to determine the full amount.','Know the contract rather than treating an option as a cheap version of a stock.','What does a call generally give its buyer?','A specified right to buy the underlying','Guaranteed ownership profit','The right to ignore every contract rule'],
 ['Intrinsic value and time value','Intrinsic value describes an option’s immediate exercise value under its terms; time or extrinsic value is the remaining premium beyond that amount. Price depends on the underlying, time, volatility expectations, rates, and other factors. An out-of-the-money option can still have value before expiration, yet expire worthless. An underlying move alone does not explain every premium change.','A call with strike $100 and underlying $105 has $5 intrinsic value per unit under a simple equity example. A $7 premium includes another $2 of extrinsic value.','Separate immediate exercise value from what buyers pay for future possibilities.','What is the intrinsic value in that simple call example?','$5 per unit','$7 regardless of the strike','$2 per unit'],
 ['Greeks describe sensitivities, not certainties','Option Greeks model sensitivity to inputs: delta to underlying price, gamma to changes in delta, theta to time, and vega to implied volatility. They depend on model assumptions and change with conditions. They are not fixed promises of future profit or exact outcomes for large moves. Multiple inputs can change together, especially around events.','An option can lose premium despite a favorable small stock move if time passes and implied volatility falls. Looking at delta alone can miss those effects.','Understand several drivers before interpreting an option’s changing price.','Can an option lose value despite a favorable underlying move?','Yes, other inputs such as time and volatility matter','No, delta guarantees profit','Only when the stock market is closed'],
 ['Expiration, exercise, assignment, and seller risk','Expiration rules, exercise style, settlement, and broker procedures differ by contract. Some options can be exercised before expiration. Sellers may be assigned and face obligations involving shares or cash. Uncovered selling can create very large or potentially unlimited losses in certain cases. Spread risk also depends on execution and assignment. Read official contract documentation and broker rules before considering an actual position.','A sold call may create an obligation to deliver shares. Having received a premium does not remove that obligation or guarantee a profit.','Complex contracts need product-specific understanding, not only a directional idea.','Does receiving an option premium remove assignment risk?','No, the seller still has contract obligations','Yes, automatically','Only when the premium is small'],
 ] as Content[]},
 {title:'Futures, Forex & Digital Assets',track:'Advanced trading',reward:'Product Risk Explorer',content:[
 ['Futures contracts and daily settlement','A futures contract specifies an underlying exposure, contract size, expiration, and settlement terms. Margin is a performance requirement rather than the full purchase price, and daily settlement can create cash demands. Tick values and leverage vary by contract. Some contracts involve delivery unless properly closed or rolled. Sprout does not trade futures; these are product concepts, not an invitation to use leverage.','A one-point change can represent different dollar amounts in two futures contracts. Knowing only the quoted price is insufficient to estimate exposure or loss.','Translate contract units into dollars and obligations before judging a move.','Is futures margin necessarily the full economic exposure?','No, exposure can be much larger','Yes, it always equals the contract value','Only for contracts with short names'],
 ['Forex pairs, spreads, and leverage','A currency pair quotes one currency relative to another. A position depends on direction, units, exchange-rate changes, spreads, and potentially financing costs. Leverage and broker regulation vary by jurisdiction. Forex availability does not mean identical liquidity at all times; weekends, holidays, and news matter. Distinguish spot currency conversion from speculative leveraged products.','Buying a currency pair expresses a relative view, not a belief that both currencies must rise against everything. A small percentage change can materially affect a leveraged account.','Currency trading requires understanding units and relative exposures.','What does a currency pair quote express?','One currency’s value relative to another','A guaranteed global return','The price of every currency at once'],
 ['Crypto custody, volatility, and product differences','Digital assets can have high volatility, platform risks, fraud risks, and different legal protections. Holding an asset with a platform differs from controlling keys in a wallet. Losing keys or sending funds incorrectly can be irreversible. A token, a fund holding exposure, and a leveraged derivative have different risks. Sprout’s directory is for US-listed stocks and ETFs, not a crypto exchange.','A platform account balance and a self-custodied wallet involve different responsibilities. Neither automatically has the same protections as an insured bank deposit.','Know what you hold, who controls it, and how access can fail.','Does a crypto balance automatically have ordinary deposit insurance?','No, verify the product and applicable protections','Yes, on every platform','Only if its price is stable'],
 ['Compare products before comparing returns','A stock, option, future, currency product, and digital asset can show similar-looking charts while having very different contracts and losses. Compare exposure, leverage, liquidity, costs, custody, settlement, jurisdiction, and maximum obligations. Market availability and platform protections also differ. Understanding one chart style does not qualify someone to trade every product.','A $100 stock share and a $100 quoted derivative may represent dramatically different exposure. The visual similarity of their candles cannot establish equivalent risk.','Product knowledge must come before transferring a strategy to an unfamiliar market.','Do similar charts imply similar product risk?','No, contracts and exposures can differ greatly','Yes, candlesticks make products equivalent','Only when both charts are green'],
 ] as Content[]},
 {title:'Psychology, Habits & Decision Quality',track:'Advanced trading',reward:'Reflective Practitioner',content:[
 ['Overconfidence and outcome bias','Overconfidence can follow a short winning streak. Outcome bias judges a decision only by its result, ignoring information and process at the time. A reckless decision can profit, and a thoughtful one can lose. Review whether you followed a defined plan and whether evidence supports the strategy across many conditions. Confidence is not a substitute for data or risk limits.','Three profitable trades do not prove that doubling size is justified. A fourth loss may reveal exposure that the earlier wins temporarily concealed.','Assess the quality of the decision separately from one outcome.','Can a profitable trade still involve poor process?','Yes, the result alone does not establish decision quality','No, profit proves the plan was sound','Only when the profit is small'],
 ['Revenge trading and loss aversion','Loss aversion can make losses feel unusually painful, while revenge trading seeks to recover quickly through impulsive entries or larger size. Notice behavior changes, pause, and use prewritten limits. A journal or mood check-in can help identify patterns but cannot diagnose mental health or guarantee discipline. Essential money and emotional wellbeing should not depend on the next trade’s result.','After a loss, entering an unrelated setup at twice the usual size to “get even” changes the risk without a planned reason. A pause can interrupt that pattern.','Protect decisions from the pressure of recovering a past result.','What is a constructive response to an impulsive urge after a loss?','Pause and review your prewritten process','Double size immediately','Trade until the account returns to its peak'],
 ['Routines, attention, and sustainable practice','A routine can include checking relevant events, reviewing risk, selecting a setup, and writing a post-trade note. Sleep, interruptions, time demands, and screen fatigue affect practical decision-making. Set a schedule you can sustain rather than treating constant monitoring as dedication. Trading is optional; learning can continue through observation and review without placing an order.','A learner with twenty minutes can review one chart and one journal entry instead of forcing multiple trades. A smaller focused session may better fit their circumstances.','A useful routine supports deliberate decisions rather than maximizing clicks.','Does every learning session need a trade?','No, observation and review also count','Yes, otherwise no learning occurs','Only on volatile days'],
 ['Process goals and honest self-assessment','Process goals describe actions under your control, such as recording a plan or respecting a size limit. Outcome goals such as a target return depend partly on uncertainty. Use both carefully and avoid changing the process simply to satisfy an arbitrary deadline. Review errors honestly, distinguish skill from luck, and revise hypotheses based on evidence rather than personal identity.','“Journal every practice trade” can be checked directly. “Earn 10% this week” cannot be guaranteed by following that habit or by using more risk.','Measure what you can improve without promising control over market outcomes.','Which is a process goal?','Record and review each planned practice decision','Guarantee a weekly return','Never experience a losing trade'],
 ] as Content[]},
 {title:'A Complete Trading Practice Plan',track:'Advanced trading',reward:'Practice Plan Builder',content:[
 ['Define your boundaries before your strategy','A practice plan names your learning purpose, available time, eligible instruments, experience level, and maximum acceptable simulated exposure. Keep personal essential funds outside any real speculative plan. Account and product requirements differ, so there is no universal cash amount that makes someone ready. Begin education now and use practice to identify gaps before considering live activity.','A new learner can choose one stock, a short observation window, and one setup to describe. That is a useful starting plan without committing real money.','Readiness is a collection of skills and circumstances, not a fixed account number.','Does reaching a particular balance automatically make someone ready?','No, knowledge and circumstances also matter','Yes, the same number applies to everyone','Only if the balance came from referrals'],
 ['Use a pre-trade checklist','A checklist should state the idea, timeframe, entry condition, size, invalidation, planned exit, relevant events, and execution assumptions. Check that the possible loss fits the account and that the product is understood. A checklist does not ensure profit; it makes missing information visible. If conditions are unclear or a limit is exceeded, pass or revise before acting.','“Price is rising” is incomplete. Add why the setup matters, how many shares, what would make you exit, and what could make the planned fill unreliable.','Make the trade decision reviewable before the outcome influences your memory.','What is a checklist’s purpose?','Expose assumptions and make a decision deliberate','Ensure every trade wins','Replace knowledge of the product'],
 ['Review metrics without chasing a ranking','Win rate, payoff size, expectancy, R-multiples, and drawdown answer different questions. A high win rate can still lose money when losses are much larger than wins. Sample size, partial exits, cash deposits, fees, and data quality affect interpretation. Sprout reports simplified sell-fill statistics, and its portfolio leaderboard is a client-reported simulated snapshot rather than verified investment performance.','Nine wins of $1 and one loss of $20 give a 90% win rate but a net $11 loss before costs. A referral deposit should not be counted as a trading gain.','Look at the distribution and assumptions behind a headline metric.','Can a high win rate still produce an overall loss?','Yes, loss size and costs also matter','No, above 50% always profits','Only when there are no charts'],
 ['Readiness, continuing education, and independent advice','Practice can develop vocabulary, routines, and familiarity, but simplified fills and generated markets differ from live conditions. Before considering real trading, assess finances, product knowledge, execution limits, and capacity for loss. Use current official sources and qualified professionals for individual legal, tax, or financial questions. Continuing to learn or choosing long-term investing instead of active trading are valid outcomes.','Someone who completes every Sprout lesson has a broader foundation, not a license or guaranteed profitable strategy. They can still choose to observe, save, or seek professional guidance.','Treat learning as an ongoing process rather than proof that uncertainty has disappeared.','What does completing the curriculum establish?','Learning progress, not guaranteed live trading success','A professional license','A promise of profitable entries'],
 ] as Content[]},
 {title:'Stock Research Workflow',track:'Advanced trading',reward:'Stock Researcher',content:[
 ['Start with the business and official filings','Research begins with what a company does, how it earns money, who its customers and competitors are, and which risks affect it. For US public companies, SEC EDGAR provides filings such as annual 10-K reports, quarterly 10-Q reports, and current 8-K reports. Company investor-relations pages also provide releases and presentations. Confirm the company identity, reporting period, and source before drawing conclusions.','A 10-K can describe revenue sources, risk factors, and audited statements. An 8-K may describe a significant event. A social-media headline is not a replacement for the filing’s actual details.','Build the company picture from primary information rather than a ticker’s popularity.','Which is a primary source for a US public company’s filings?','SEC EDGAR','A viral comment thread','An anonymous price target'],
 ['Compare financials with the right peers','Review revenue, margins, cash flow, balance-sheet strength, and how they change over several periods. Compare businesses with similar economics, and note accounting differences, one-time items, currency effects, and seasonality. Ratios are useful questions, not automatic decisions. A strong company can still be a poor purchase at an unsuitable valuation or for a goal needing stable cash.','A retailer’s holiday quarter should not be compared casually with another company’s quiet season. A software business and a bank may need different valuation measures.','Make comparisons consistent before interpreting a difference as an opportunity.','What improves a financial comparison?','Comparable periods, business models, and accounting context','Comparing any two headline numbers','Using only the most favorable quarter'],
 ['Evaluate news, estimates, and source quality','Separate reported facts, estimates, opinions, and rumors. Check dates, original documents, conflicts of interest, and what was known when a claim was made. Analyst targets rely on assumptions and can change. News can be accurate while its interpretation remains uncertain. A popular summary may omit dilution, debt, or an adverse detail in the original release.','A target price is an analyst’s view under assumptions, not a promised future quote. A recycled article can describe an old event as if it happened today.','Source quality and timing matter as much as the confidence of a claim.','Is an analyst target price a guaranteed future price?','No, it is an estimate with assumptions','Yes, by regulation','Only if several analysts agree'],
 ['Write a research thesis and what would change it','A research thesis states the idea, evidence, valuation assumptions, timeframe, main risks, and what would contradict it. Include alternative explanations and record sources with dates. A watchlist is for observation, not a commitment to buy. Review new evidence consistently rather than adding reasons to defend a position after the original idea fails.','A thesis might depend on improving margins and manageable debt. Falling cash flow or a debt refinancing problem could require revisiting it even if the chart briefly rises.','A written thesis makes research easier to challenge and improve.','What belongs in a research thesis?','Evidence, risks, assumptions, and invalidation','Only a hoped-for target price','Only supporting opinions'],
 ] as Content[]},
 {title:'Bullish & Bearish Market Context',track:'Advanced trading',reward:'Market Direction Reader',content:[
 ['Bullish, bearish, and neutral views','Bullish describes an expectation of rising prices; bearish describes an expectation of falling prices. A neutral view may expect limited direction or insufficient evidence. A bull or bear market describes a broader period using context or particular definitions, not the same thing as one green or red candle. An opinion is a hypothesis, not proof or a recommendation.','A stock can have a green day during a broader downtrend. An investor can be bullish over years while expecting a difficult week.','Use directional words with a timeframe and supporting evidence.','Does one green candle prove a bull market?','No, broader context and timeframe matter','Yes, automatically','Only if the candle has no wick'],
 ['Direction can differ across timeframes','Daily, weekly, and intraday charts summarize different windows. Higher highs and higher lows may describe an observed uptrend, while lower highs and lower lows may describe a downtrend. Range-bound movement may lack clear direction. A shorter-term rally can occur within a longer-term decline. Use the timeframe relevant to the idea and acknowledge conflicting evidence.','A five-minute chart may rise while the weekly chart is falling. Neither observation cancels the other; they answer different questions about the same price history.','Avoid changing timeframes only to find a chart that supports your preferred direction.','Can short- and long-term directions differ?','Yes, they describe different windows','No, every timeframe must match','Only when prices are delayed'],
 ['Build a bullish or bearish case from evidence','A directional case can combine business results, valuation, events, liquidity, and observed price behavior. Evidence may support multiple interpretations, and indicators often overlap. State assumptions and what would contradict the case. A bearish view does not require opening a short position, especially when you do not understand borrowing or leverage. Observing or reducing exposure can also be decisions.','Weakening margins and lower price swings can support a bearish hypothesis, but unexpected good news may change it. Sprout lets you sell owned shares; it does not execute short sales.','Translate a view into an informed plan rather than assuming it demands a trade.','Must a bearish view lead to a short sale?','No, observing or changing owned exposure are alternatives','Yes, every bearish view requires borrowing','Only when the account is small'],
 ['Use scenarios instead of certainty','Create a bullish, bearish, and neutral scenario with conditions that would support each. Estimate possible exposure and practical responses without assigning invented certainty. A failed setup should trigger a review of the plan, not an unlimited extension of the original thesis. Your role is to respond thoughtfully to new evidence rather than force the market to match a forecast.','If price holds an observed area, you might continue studying one scenario. If it breaks and relevant business evidence weakens, another scenario may deserve attention. Neither path guarantees the next move.','Scenario thinking makes uncertainty explicit and helps reduce attachment to one outcome.','What makes a scenario plan useful?','Conditions and responses for multiple outcomes','A promise that one forecast must happen','Ignoring any evidence that conflicts'],
 ] as Content[]},
 {title:'Public Insider Transactions',track:'Advanced trading',reward:'Disclosure Reader',content:[
 ['Public insider filings versus nonpublic information','Company officers, directors, and certain significant owners may report securities ownership and transactions under US disclosure rules. Public filings can be researched lawfully. Material nonpublic information is different: trading or tipping on it can violate securities law. Do not solicit confidential tips. Use publicly available filings and verify the applicable rules rather than assuming access to an employee makes information safe to trade on.','An executive’s published SEC ownership filing is public research material. A confidential unreleased earnings result shared privately is a different situation, even if you know the employee personally.','Distinguish transparent disclosures from confidential information before using a source.','Which is appropriate public research material?','An officially published ownership filing','Unreleased earnings from a confidential source','A private tip guaranteed to move the price'],
 ['Forms 3, 4, and 5: what they report','Under relevant US rules, Form 3 reports initial beneficial ownership, Form 4 reports changes, and Form 5 can report certain annual items or exceptions. Many Form 4 changes are generally due within two business days, subject to the rules and circumstances. Read the transaction date separately from the filing date. Inspect direct versus indirect ownership and footnotes. Use SEC EDGAR and current official instructions.','A Form 4 filed today may describe a transaction from an earlier day. A holding through a trust may be indirect ownership and need explanation in the notes.','Understand what was disclosed and when rather than assuming a filing is a real-time signal.','Is the filing date necessarily the transaction date?','No, they can differ','Yes, always','Only for transactions over $1 million'],
 ['Read transaction codes before calling it buying or selling','Codes distinguish different events. In common Form 4 reporting, P can indicate an open-market or private purchase and S an open-market or private sale. A can indicate an award, M an exercise or conversion, F shares used for an exercise price or tax withholding, and G a gift. Read the complete code definitions, security type, quantities, prices, and footnotes; a transfer or award is not automatically a discretionary market purchase.','An executive receiving shares as compensation is not necessarily spending personal cash to buy in the market. A tax-withholding transaction can reduce reported shares without expressing a bearish forecast.','A simple “insider bought” label can hide a very different economic event.','Does a share award necessarily mean an open-market purchase?','No, the transaction type matters','Yes, every increase is a cash purchase','Only if the person is a director'],
 ['Context, trading plans, and limits of insider signals','Insider activity can reflect compensation, diversification, taxes, personal liquidity, or a view of the business. Transactions may occur under prearranged trading plans such as Rule 10b5-1 plans, subject to applicable conditions. Consider size relative to existing holdings, repeated patterns, multiple insiders, timing, and notes. A disclosed purchase or sale cannot reveal every motive or guarantee a future price move.','A planned sale representing a small part of a large holding differs from a large discretionary purchase. Both still need business and valuation context, and neither is an automatic entry instruction.','Use disclosures as one research input instead of treating an insider’s action as certainty.','Does a public insider sale prove the stock will fall?','No, motives and market outcomes are uncertain','Yes, every insider sale is a warning of a crash','Only if the sale was planned'],
 ] as Content[]},

 ...strategyModules,
];
export const expandedLessons:Lesson[]=expandedModules.flatMap((module,m)=>module.content.map((c,i)=>({id:60+m*4+i,level:13+m,title:c[0],explanation:c[1],example:c[2],why:c[3],quiz:{question:c[4],options:[c[6],c[5],c[7]],answer:1,explanation:c[2]+' '+c[3]}})));
